const row = $json._row || {};
const images = row.images || [];
if (!images.length) return [];
return images.map((image, index) => ({ json: { ...$json, file_id: image.fileId || '', file_name: image.fileName || `google-drive-image-${index + 1}`, original_url: image.originalUrl || image.previewUrl || '', image_index: index, image_count: images.length } }));

let imageUrl = String($json.original_url || '').trim();
const driveId = imageUrl.match(/(?:open\?id=|uc\?(?:export=[^&]+&)?id=|thumbnail\?id=|file\/d\/|[?&]id=)([A-Za-z0-9_-]+)/)?.[1] || String($json.file_id || '').trim();
if (driveId) imageUrl = `https://drive.google.com/uc?export=download&id=${driveId}`;
if (imageUrl.includes('dropbox.com') && imageUrl.includes('dl=0')) imageUrl = imageUrl.replace('dl=0', 'dl=1');
if (imageUrl.includes('sharepoint.com') || imageUrl.includes('1drv.ms')) imageUrl = imageUrl.split('?')[0] + '?download=1';
return { json: { ...$json, file_id: driveId, direct_download_url: imageUrl, preview_url: driveId ? `https://drive.google.com/uc?export=view&id=${driveId}` : imageUrl } };

const row = $('Chuẩn hóa row và nền tảng').first().json._row || {};
const aiItem = $input.first()?.json || {};

// Lấy text từ cấu trúc output của OpenAI
let raw = '';

if (Array.isArray(aiItem.output)) {
  raw = aiItem.output
    .flatMap(msg => msg.content || [])
    .filter(content => content.type === 'output_text')
    .map(content => content.text || '')
    .join('\n');
}

// fallback nếu sau này format output thay đổi
if (!raw) {
  raw = String(
    aiItem.output_text ||
    aiItem.response ||
    aiItem.text ||
    ''
  );
}

// Xóa ```json ... ``` nếu có
raw = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed = {};

try {
  parsed = JSON.parse(raw);
} catch (error) {
  // fallback: tìm JSON object trong text
  try {
    const match = raw.match(/\{[\s\S]*\}/);
    parsed = match ? JSON.parse(match[0]) : {};
  } catch {
    parsed = {};
  }
}

return [
  {
    json: {
      _row: row,
      fb_content: String(parsed.facebook || '').trim(),
      li_content: String(parsed.linkedin || '').trim(),
    }
  }
];

const data = $input.first()?.json || {};
const row = data._row || {};
return [{ json: { sourceRowId: row.sourceRowId, employeeName: row.employeeName, originalNote: row.note, images: data.images || [], facebookContent: data.fb_content || '', linkedinContent: data.li_content || '', sheetRow: row.sheetRow } }];

const sourceItems = $('Đổi link chia sẻ thành link tải').all();

const first = sourceItems[0]?.json || {};
const row = first._row || {};

const images = sourceItems
  .map((item, index) => {
    const source = item.json || {};

    const fileId =
      source.file_id ||
      row.images?.[index]?.fileId ||
      '';

    const fileName =
      source.file_name ||
      row.images?.[index]?.fileName ||
      `google-drive-image-${index + 1}`;

    // Tự tạo link preview Google Drive
    const url = fileId
      ? `https://drive.google.com/file/d/${fileId}/preview`
      : '';

    return {
      fileId,
      fileName,
      url
    };
  })
  .filter(image => image.fileId);

return [
  {
    json: {
      _row: row,
      images
    }
  }
];

const output = [];

for (const item of $input.all()) {
  const row = item.json || {};

  const rawImages = String(
    row['Hình ảnh công việc'] ||
    row.linkHinhAnh ||
    row.images ||
    ''
  ).trim();

  const note = String(
    row['Ghi chú công việc'] ||
    row['Ghi chú'] ||
    row.note ||
    ''
  ).trim();

  const platformRaw = String(
    row['Nền tảng đăng'] ||
    row.platform ||
    ''
  ).toLowerCase();

  const hasFacebook = /facebook|fanpage/.test(platformRaw);
  const hasLinkedIn = /linkedin/.test(platformRaw);

  const imagePattern =
    /https?:\/\/drive\.google\.com\/(?:open\?id=|file\/d\/)([A-Za-z0-9_-]+)/g;

  const ids = [...rawImages.matchAll(imagePattern)]
    .map((match) => match[1]);

  const images = [...new Set(ids)].map((fileId, index) => ({
    fileId,
    fileName: `google-drive-image-${index + 1}`,
    originalUrl: `https://drive.google.com/open?id=${fileId}`,
    previewUrl: `https://drive.google.com/file/d/${fileId}/preview`,
  }));

  const sourceRowId = String(
    row['Dấu thời gian'] ||
    row.Timestamp ||
    row.timestamp ||
    row.row_number ||
    `${note}-${rawImages}`
  ).trim();

  const employeeName = String(
    row['Tên nhân viên'] ||
    row['Tên'] ||
    row.Username ||
    row['Email address'] ||
    'Chưa xác định'
  ).trim();

  // QUAN TRỌNG: copy dữ liệu, không truyền row trực tiếp
  const sheetRow = { ...row };

  item.json._row = {
    sourceRowId,
    employeeName,
    note,

    platform:
      hasFacebook && hasLinkedIn
        ? 'both'
        : hasFacebook
          ? 'facebook'
          : hasLinkedIn
            ? 'linkedin'
            : 'both',

    targetFB:
      hasFacebook || (!hasFacebook && !hasLinkedIn),

    targetLI:
      hasLinkedIn || (!hasFacebook && !hasLinkedIn),

    sheetRow,
    imageLink: rawImages,
    images,
  };

  output.push(item);
}

return output;
